// Emit config.d/22-peer-gfx1030.yaml: a peers-only route to a LIVE
// local-inference llama-swap instance.  Generated by generate.sh only on
// hosts that do NOT serve local models natively (there a locally-capable
// multipurpose instance would just self-route); the gfx1030 models are
// reached through a `peers` entry, never through local `models` entries (a
// cmd-less local entry would shadow peer routing and fail with "empty
// command" at swap time).
//
// Detection: candidate base URLs are probed in order until one answers
// GET /models with HTTP 200 using llama-swap's `curl -u :$API_KEY`
// convention (Basic base64(":key")).  The first reachable instance wins:
//
//   1. $PEER_BASE_URL            (explicit override)
//   2. bazzite tailscale URL     (https reverse proxy — the world-visible
//      FQDN funnel of the LAN llama-swap instance; gfx1030 models arrive
//      FQN-prefixed as "gfx1030/<id>" and are normalized back to the bare
//      ids the upstream instance expects)
//
// localhost candidates are NOT probed: the LAN instance lives on :8080, and
// the legacy :18080 local-inference port is deprecated (pre-squash two-
// instance split).  If no instance answers, do nothing: the existing
// config.d/ is left untouched and the remaining generators provide the
// baseline.
//
// Env: PEER_API_KEY (auth), PEER_BASE_URL (optional explicit base URL).
// Usage: node generate-gfx1030-models.mjs

import { fetchModelsJson, writeConfigD } from "./gen-lib.mjs";

const API_KEY = (process.env.PEER_API_KEY || "").trim();

const BAZZITE_ROUTER_TAILSCALE_URL =
  "https://bazzite.coelacanth-barb.ts.net/8654b72a-de9b-402b-abe6-7201dcb38438";

const CANDIDATE_BASE_URLS = [
  process.env.PEER_BASE_URL,
  BAZZITE_ROUTER_TAILSCALE_URL,
].filter(Boolean);

const PEER_ID = "gfx1030";
const OUTPUT_NAME = "22-peer-gfx1030.yaml";

function basicAuthHeader(key) {
  return { Authorization: `Basic ${Buffer.from(`:${key}`).toString("base64")}` };
}

async function detectBaseURL() {
  const failures = [];
  for (const baseUrl of CANDIDATE_BASE_URLS) {
    try {
      const { data } = await fetchModelsJson(baseUrl, basicAuthHeader(API_KEY));
      const ids = data.map((m) => m?.id).filter(Boolean);
      // Router-proxied candidates list FQN ids across ALL peer families;
      // keep only the gfx1030 family, normalized to the bare ids the
      // upstream instance expects.  Bare-id candidates (the gfx1030 instance
      // itself) pass through unchanged.
      const fqnPrefix = "gfx1030/";
      const gfxIds = ids
        .filter((id) => id.startsWith(fqnPrefix))
        .map((id) => id.slice(fqnPrefix.length));
      const modelIds = [...new Set(gfxIds.length ? gfxIds : ids)].sort();
      if (!modelIds.some((id) => id.includes("-GGUF"))) {
        throw new Error("listing contains no local GGUF models for gfx1030");
      }
      return { baseUrl, modelIds };
    } catch (err) {
      failures.push(`${baseUrl}: ${err.message}`);
    }
  }
  throw new Error(`no gfx1030 instance reachable (${failures.join(" | ")})`);
}

async function main() {
  if (!CANDIDATE_BASE_URLS.length || !API_KEY) {
    console.warn(
      "  note: PEER_API_KEY or PEER_BASE_URL candidates unavailable — " +
        "cannot probe any gfx1030 instance; leaving config.d/ as-is",
    );
    return;
  }

  let detected;
  try {
    detected = await detectBaseURL();
  } catch (err) {
    console.warn(
      `  note: ${err.message} — keeping existing config.d/${OUTPUT_NAME}`,
    );
    return;
  }
  if (detected.modelIds.length === 0) {
    console.warn(
      `  note: ${detected.baseUrl}/models returned no models; keeping existing config.d/`,
    );
    return;
  }

  const peer = { proxy: detected.baseUrl, models: detected.modelIds };
  // Emitted as a ${env.*} reference resolved by llama-swap at load time, so
  // the serving runtime must export PEER_API_KEY too (see run.sh/run-native.sh).
  if (process.env.PEER_API_KEY !== undefined) {
    peer.apiKey = "${env.PEER_API_KEY}";
  }
  writeConfigD(OUTPUT_NAME, { peers: { [PEER_ID]: peer } });
  console.warn(
    `  synced ${detected.modelIds.length} models via peer "${PEER_ID}" -> ${detected.baseUrl}`,
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
